<script setup lang="ts">
import ImportDialog from "./ImportDialog.vue";
import{ref}from'vue';import Modal from'../ui/Modal.vue';import Icon from'../ui/Icon.vue';import{api}from'../app/api';defineProps<{trips:any[];user:any}>();const emit=defineEmits<{open:[id:string];logout:[]}>();const importing=ref(false);const create=ref(false),error=ref(''),busy=ref(false);const form=ref({title:'',startDate:new Date().toISOString().slice(0,10),endDate:new Date(Date.now()+2*86400000).toISOString().slice(0,10),timeZone:'Asia/Shanghai'});async function submit(){busy.value=true;try{const t=await api('/trips','POST',form.value);create.value=false;emit('open',t.id)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="trips-page"><header class="home-header"><div class="brand"><span class="brand-mark"><Icon name="map"/></span>行间</div><button class="subtle" @click="emit('logout')">{{user.username}} <Icon name="logout" :size="18"/></button></header><section class="home-hero"><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>一起，去看看。</h1><p>从一个想法，到一段共同的旅程。</p><button class="primary" @click="create=true"><Icon name="plus"/>新建旅行</button><button class="text-button" @click="importing=true">导入已有备份</button></section><section class="trip-grid"><button v-for="(trip,i) in trips" :key="trip.id" class="trip-card" @click="emit('open',trip.id)"><div :class="['trip-cover','cover-'+i%3]"><Icon name="map" :size="64"/><span>{{trip.archived?'已归档':'共同规划中'}}</span><div class="cover-contour"></div></div><div class="trip-card-body"><h2>{{trip.title}}</h2><p><Icon name="calendar" :size="16"/>{{trip.start_date}} — {{trip.end_date}}</p><div class="trip-bottom"><span>{{trip.role==='owner'?'我创建的':trip.role==='editor'?'共同编辑':'仅查看'}}</span><Icon name="arrow"/></div></div></button><div v-if="!trips.length" class="home-empty"><Icon name="map" :size="40"/><h3>旅程从这里开始</h3><p>创建一趟旅行，邀请同行人，<br>一起安排路线和行李。</p></div></section><footer class="home-footer">少一点忙乱，多一点期待。<span>旅行默认仅同行人可见</span></footer><ImportDialog v-if="importing" @close="importing=false" @open="emit('open',$event)"/><Modal v-if="create" title="新的旅程" @close="create=false"><form class="editor-form" @submit.prevent="submit"><label>旅行名称<input v-model="form.title" required maxlength="120" autofocus placeholder="例如：杭州慢游三日"></label><div class="form-grid"><label>开始日期<input v-model="form.startDate" type="date" required></label><label>结束日期<input v-model="form.endDate" type="date" required></label></div><label>旅行时区<input v-model="form.timeZone" required></label><p class="error" v-if="error">{{error}}</p><button class="primary full" :disabled="busy">创建旅行</button></form></Modal></div></template>

